#pragma once
#include <string_view>
namespace neurogenic { enum class CommandId { transport_start, transport_stop, pattern_generate, timeline_generate, timeline_mutate_track, timeline_regenerate, timeline_variation, timeline_commit, timeline_discard, timeline_query, sample_load, sample_replace, sample_unload, sample_query }; constexpr std::string_view stable_id(CommandId id){switch(id){case CommandId::transport_start:return"transport.start";case CommandId::transport_stop:return"transport.stop";case CommandId::pattern_generate:return"pattern.generate";case CommandId::timeline_generate:return"timeline.generate.v1";case CommandId::timeline_mutate_track:return"timeline.mutate-track.v1";case CommandId::timeline_regenerate:return"timeline.regenerate.v1";case CommandId::timeline_variation:return"timeline.variation.v1";case CommandId::timeline_commit:return"timeline.commit.v1";case CommandId::timeline_discard:return"timeline.discard.v1";case CommandId::timeline_query:return"timeline.query.v1";case CommandId::sample_load:return"sample.load.v1";case CommandId::sample_replace:return"sample.replace.v1";case CommandId::sample_unload:return"sample.unload.v1";case CommandId::sample_query:return"sample.query.v1";}return"unknown";} }
